.github/workflows/groundhog-release.yml:.matrix_source:
matrix:
        # One deb per release: library names differ (libsecp256k1-1 on
        # 24.04, -2 on Debian 13, newer on 26.04), so a 24.04 build does
        # not install elsewhere. The version carries the distribution;
        # dpkg names the file _amd64 or _arm64.
        distro:
          - { image: 'ubuntu:24.04', name: 'Ubuntu 24.04', tag: ubuntu24.04 }
          - { image: 'ubuntu:26.04', name: 'Ubuntu 26.04', tag: ubuntu26.04 }
          - { image: 'debian:13',    name: 'Debian 13',    tag: debian13 }
        arch: [x86_64, aarch64]
        include:
          - { arch: x86_64,  runner: ubuntu-24.04 }
          - { arch: aarch64, runner: ubuntu-24.04-arm }

matrix:
        include:
          - { arch: x86_64,  runner: ubuntu-24.04 }
          - { arch: aarch64, runner: ubuntu-24.04-arm }

matrix:
        include:
          - { arch: x86_64,  runner: ubuntu-24.04 }
          - { arch: aarch64, runner: ubuntu-24.04-arm }

matrix:
        include:
          - { system: x86_64-linux,  runner: ubuntu-24.04 }
          - { system: aarch64-linux, runner: ubuntu-24.04-arm }

